#define T iTime
#define PI 3.141596
#define TAU 6.283185
#define S smoothstep
#define s1(v) (sin(v)*.5+.5)
const float EPSILON = 1e-3;

mat2 rotate(float a){
  float s = sin(a);
  float c = cos(a);
  return mat2(c,-s,s,c);
}

float fbm(vec3 p){
  float amp = 1.;
  float fre = 1.;
  float n = 0.;
  for(float i =0.;i<4.;i++){
    n += abs(dot(cos(p), vec3(.1)));
    amp *= .5;
    fre *= 2.;
  }
  return n;
}



void mainImage(out vec4 O, in vec2 I){
  vec2 R = iResolution.xy;
  vec2 uv = (I*2.-R)/R.y;
  vec2 m = (iMouse.xy*2.-R)/R * PI * 2.;

  O.rgb *= 0.;
  O.a = 1.;

  vec3 ro = vec3(0.,0.,-10.);

  vec3 rd = normalize(vec3(uv, 1.));

  float zMax = 50.;
  float z = .1;

  mat2 mx = rotate(T*.5);
  mat2 my = rotate(T*.5);
  if(iMouse.z>0.){
    mx = rotate(m.x);
    my = rotate(m.y);
  }


  vec3 col = vec3(0);
  vec3 p;
  for(float i=0.;i<100.;i++){
    p = ro + rd * z;

    p.xz *= mx;
    p.yz *= my;

    float d = length(p) - 5.;
    float d1;
    {
      vec3 q = p;
      q.xy *= rotate(T+i*3.);
      q.xz *= rotate(T+i*2.);
      q.yz *= rotate(T+i*1.);
      d1 = length(sin(q.xz*.08))-.1;
      d1 = abs(d1)*.6+.001;
      d1 = max(d, d1);
    }
    d = abs(d)*.3+.01;
    d = min(d, d1);



    col += s1(vec3(3,2,1)+dot(p,vec3(.4)))/d;
    if(d<EPSILON || z>zMax) break;
    z += d;
  }
  col = tanh(col / 2e3);



  O.rgb = col;
}
